			function strLengthChk(str) {
			    var len = 0;
			    for (var i =0;i<str.length;i++) {
			        console.log("여기서 오류냐? 33333");
			        if (escape(str.charAt(i).length == 0)) {
			            len++;
			        }
			        len++;
			    }
			    return len;
			}

			function validateChk() {
			    var dm = app.lookup("dmInstInfo");
			    var chk = true;
			    
			    if("" != dm.getValue("RPRS_ADDR") && null != dm.getValue("RPRS_ADDR")) {
			        var len = strLengthChk(dm.getValue("RPRS_ADDR"));
			        
			        if(len > 100) {
			            util.Msg.alert(app, "주소가 너무 깁니다.");
			            return false;
			        }
			    }
			    
			    if("" != dm.getValue("RPRS_TELNO") && null != dm.getValue("RPRS_TELNO")) {
			        var telno = dm.getValue("RPRS_TELNO").replace(/(\d{2,3})(\d{3,4})(\d{4})/, '$1-$2-$3');
			        dm.setValue("RPRS_TELNO", telno);
			    }
			    if("" != dm.getValue("RPRS_FXNO") && null != dm.getValue("RPRS_FXNO")) {
			        var faxNo = dm.getValue("RPRS_FXNO").replace(/(\d{2,3})(\d{3,4})(\d{4})/, '$1-$2-$3');
			        dm.setValue("RPRS_FXNO", faxNo);
			    }
			    if("" != dm.getValue("HPGE_ADDR") && null != dm.getValue("HPGE_ADDR")) {
			        var urlChk = urlTypeChk(dm.getValue("HPGE_ADDR"));
			        if(!urlChk){
			            util.Msg.alert(app, "홈페이지 URL 양식이 아닙니다.");
			            return false;
			        }
			    }
			    app.lookup("grpBoardDtl").redraw();
			    return chk;
			}

			function urlTypeChk(domain) {
			    var url = /^(((http(s?))\:\/\/)?)([0-9a-zA-Z\-]+\.)+[a-zA-Z]{2,6}(\:[0-9]+)?(\/\S*)?/;
			    return url.test(domain);
			}
